effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec2 px = acScreenNorm * acResolution;
    float a = radians(angle);
    float c = cos(a), s = sin(a);
    vec2 rot = vec2(px.x * c - px.y * s, px.x * s + px.y * c);
    vec2 cell = floor(rot / size) * size + size * 0.5;
    vec2 centro = vec2(cell.x * c + cell.y * s, -cell.x * s + cell.y * c);
    vec2 uv = centro / acResolution;

    vec3 amostra = texture(inputImg, clamp(uv, 0.0, 1.0)).rgb;
    float l = dot(amostra, LUMA);
    float raio = sqrt(1.0 - l) * size * 0.5;
    float d = distance(rot, cell);
    float pt = 1.0 - smoothstep(raio - softness * size, raio + softness * size, d);
    vec3 cor = mix(bgColor.rgb, dotColor.rgb, pt);
    float alphaOrig = texture(inputImg, acScreenNorm).a;
    fragColor = vec4(cor, alphaOrig);
}
